INSERT OR IGNORE INTO resumes ("id", "userId", "slug", "fullName", "contactEmail", "contactPhone", "contactLinkedIn", "photoUrl", "title", "profession", "templateKey", "visibility", "accessPassword", "accessPasswordExpiresAt", "coverLetterEnabled", "generatedCoverLetter", "recruiterModeEnabled", "recruiterLocation", "recruiterAvailability", "recruiterClearance", "recruiterWorkAuthorization", "recruiterExpectedSalary", "recruiterRemotePreference", "combineExperienceFormat", "answers", "experience", "education", "awards", "achievements", "skillsAndTools", "referencesEnabled", "references", "referencesRecruiterModeOnly", "generatedSummary", "generatedBullets", "viewCount", "createdAt", "updatedAt") VALUES ('vm5X-ulMh4ht', 'Ty55eG7_mqGs', 'solutions-architect-shWKxE', 'CJ Owens', 'cjowens@mac.com', '730.222.0909', 'https://www.linkedin.com/in/cjowens', 'data:image/jpeg;base64,', 'Solutions Architect', 'software-engineer', 'portrait', 'password', '', NULL, 1, 'Dear Hiring Manager,

I am writing to express my interest in Solutions Architect opportunities. Results-driven Software Engineer with 21+ years of experience specializing in C#, resourceful problem-solver who combines clean, maintainable code, systems-level thinking, and close collaboration with cross-functional teams to ship reliable software faster. Known for clear technical communication, ownership, and a habit of continuous learning. Most recently, I served as Lead Software Engineer at Blue Block, where I sharpened my ability to deliver results under pressure and collaborate effectively across teams.

I would welcome the opportunity to discuss how my background and skills align with your team''s needs. Thank you for your time and consideration.

Sincerely,
CJ Owens', 1, 'Washington DC', '3 weeks from offer acceptance', 'top-secret-sci', 'us-citizen', '215,000', 'flexible', 1, '{"languages":"C#, ASP.Net","frameworks":".NET, React","cloudPlatforms":"Azure, AWS, GCP","certifications":"MCAPT, MCS, MCSA, MCSP, MCAST, EA, AWSCT","methodologies":"Agile, Scrum, EA","devOps":"AzureDevOps, GitLab","ciCd":"GitLab","security":"Net+, Security+, CISSP","gitHub":"http://github.com/myrepo","yearsExperience":"21"}', '[{"company":"Intellibridge","title":"Data analyst","startDate":"2008-02","endDate":"2013-06","current":false,"id":"b468c8d4-806a-4ece-8d4a-4e3c716f3a09","city":"OKC","state":"OK"},{"company":"RC Cyclone ","title":"Data Engineer","startDate":"2013-07","endDate":"2014-12","current":false,"id":"82db28af-b52b-44ff-b066-9a821aa8ef91","city":"Dallas","state":"TX"},{"company":"Mantech","title":"Solutions Associate","startDate":"2014-12","endDate":"2019-02","current":false,"id":"41a09d9c-a01a-4279-8d94-c4005fe61829","city":"Dallas","state":"TX"},{"company":"CACI","title":"Software engineer","startDate":"2019-02","endDate":"2023-10","current":false,"id":"c85f218f-cc19-44b4-8792-96a1ac2b53ef","city":"Houston","state":"TX"},{"company":"Blue Block","title":"Lead Software Engineer","startDate":"","endDate":null,"current":true,"id":"e0e2c06f-6888-43e0-83d7-df81d91f4be1","city":"Charlotte","state":"NC"}]', '[{"school":"Humboldt University","degree":"B.S.","fieldOfStudy":"Computer Science","startDate":"2003-01","endDate":"2007-05","current":false}]', '[]', '[{"challenge":"Work stream was very inefficient and there were not enough engineers to produce the work on time.","action":"Designed a workflow that involved other teams to help supplement the non-descript work.","result":"59% increase in work productivity.","experienceId":"41a09d9c-a01a-4279-8d94-c4005fe61829"},{"challenge":"The project budget was cut by 30% yet the amount of work was unchanged. Our workforce went from 15 engineers to 10.","action":"The engineering team, led by me, looked through each tool and application set and made refinements to the process flow and how we conducted business.","result":"Out timelines and deliverables were not only satisfied on time but 25% of our deliverables were delivered earlier.","experienceId":"b468c8d4-806a-4ece-8d4a-4e3c716f3a09"},{"challenge":"As a lead engineer on the project, we lacked a real sense of direction and proper alignment to the objectives.","action":"As the lead engineer, the decision was made to create a project plan and roadmap to track to the current objectives and the phases to which the work would need to process through until success.","result":"The project finished on time resulting in a performance grade of excellent. ","experienceId":"c85f218f-cc19-44b4-8792-96a1ac2b53ef"}]', '[{"label":"System design","category":"skill"},{"label":"Code review","category":"skill"},{"label":"Mentoring","category":"skill"},{"label":"Cross-team collaboration","category":"skill"},{"label":"TypeScript","category":"tool"},{"label":"Python","category":"tool"},{"label":"React","category":"tool"},{"label":"Node.js","category":"tool"},{"label":"Git","category":"tool"},{"label":"CI/CD","category":"tool"}]', 1, '[{"name":"Curt Leeve","companyPosition":"Project Manager","company":"Mantech","email":"cl@mantech.com","phone":"555-121-3344","affiliation":"Colleague","dateObserved":"2015-02","dateObservedStart":"2015-01","dateObservedEnd":"2018-06"}]', 1, 'Results-driven Software Engineer with 21+ years of experience specializing in C#, resourceful problem-solver who combines clean, maintainable code, systems-level thinking, and close collaboration with cross-functional teams to ship reliable software faster. Known for clear technical communication, ownership, and a habit of continuous learning.', '["Designed a workflow that involved other teams to help supplement the non-descript work, in response to work stream was very inefficient and there were not enough engineers to produce the work on time, resulting in 59% increase in work productivity.","The engineering team, led by me, looked through each tool and application set and made refinements to the process flow and how we conducted business, in response to the project budget was cut by 30% yet the amount of work was unchanged. Our workforce went from 15 engineers to 10, resulting in out timelines and deliverables were not only satisfied on time but 25% of our deliverables were delivered earlier.","As the lead engineer, the decision was made to create a project plan and roadmap to track to the current objectives and the phases to which the work would need to process through until success, in response to as a lead engineer on the project, we lacked a real sense of direction and proper alignment to the objectives, resulting in the project finished on time resulting in a performance grade of excellent."]', 243, '2026-08-02T20:54:22.745Z', '2026-08-10T02:24:42.385Z');
